* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--sans);
  background: var(--bg);
  color: var(--text);
  font-size: 13px;
}

h1, h2, h3 {
  margin: 0;
  font-weight: 600;
}

.section {
  border-bottom: 1px solid var(--border);
  padding: 10px 14px;
}

.section:last-child {
  border-bottom: none;
