import { buildInfrastructureInfo } from "../parsers/index.js";
import type { Capture } from "../parsers/types.js";
import { clearCapture, saveCapture } from "../utils/storage.js";

/**
 * Merges chrome.webRequest's HttpHeader[] into a plain header map. Multiple
 * headers with the same name (legal for Server-Timing, Set-Cookie, etc.)
 * are joined with ", " to match how the Fetch API's Headers object behaves,
 * so the parsing layer sees the same shape either way.
 */
function toHeaderMap(headers: chrome.webRequest.HttpHeader[] | undefined): Record<string, string> {
  const map: Record<string, string> = {};
  for (const h of headers ?? []) {
    if (h.value === undefined) continue;
    const name = h.name.toLowerCase();
    map[name] = name in map ? `${map[name]}, ${h.value}` : h.value;
  }
  return map;
}

chrome.webRequest.onResponseStarted.addListener(
  (details) => {
    // onResponseStarted only fires for the final, non-redirect response, so
    // this is always the document that actually rendered - not an
    // intermediate 3xx hop.
    if (details.type !== "main_frame" || details.tabId < 0) return;

    const headers = toHeaderMap(details.responseHeaders);
    const info = buildInfrastructureInfo(headers);

    const capture: Capture = {
      meta: {
        url: details.url,
        tabId: details.tabId,
        timestamp: Date.now(),
        statusCode: details.statusCode,
      },
      info,
    };

    void saveCapture(details.tabId, capture);
  },
  { urls: ["http://*/*", "https://*/*"], types: ["main_frame"] },
  ["responseHeaders"],
);

chrome.tabs.onRemoved.addListener((tabId) => {
  void clearCapture(tabId);
});

